@GetMapping
@Audited(page = "todo", action = "search")
public String index(
        @Valid @ModelAttribute TodoSearchForm form,
        BindingResult bindingResult,
        Model model) {

    // バリデーションエラーがある場合は空のリストを表示
    if (bindingResult.hasErrors()) {
        model.addAttribute("todos", java.util.List.of());
        model.addAttribute("page", new PageResult<>(java.util.List.of(), 0, 0, form.getSize()));
        model.addAttribute("validationErrors", bindingResult.getAllErrors());
        return "todo/index";
    }

    PageResult<TodoItem> result = todoService.search(
            form.getQ(),
            form.toCompletedBoolean(),
            form.toDueFromDate(),
            form.toDueToDate(),
            form.getPage(),
            form.getSize());

    model.addAttribute("todos", result.getItems());
    model.addAttribute("page", result);
    model.addAttribute("q", form.getQ());
    model.addAttribute("completed", form.getCompleted());
    model.addAttribute("dueFrom", form.getDueFrom());
    model.addAttribute("dueTo", form.getDueTo());
    model.addAttribute("size", form.getSize());

    return "todo/index";
}

