private static LocalDate parseDate(String text) {
    if (text == null || text.isBlank()) {
        return null;
    }
    try {
        return LocalDate.parse(text, DATE_FORMATTER);
    } catch (DateTimeParseException ex) {
        return null;
    }
}

/**
 * completed文字列をBoolean型に変換
 * 
 * @return Boolean値、または空文字/nullの場合はnull
 */
public Boolean toCompletedBoolean() {
    if (completed == null || completed.isBlank()) {
        return null; // NOSONAR: nullを返すことが意図的な設計
    }
    return Boolean.parseBoolean(completed);
}

/**
 * dueFrom文字列をLocalDate型に変換
 * 
 * @return LocalDate、またはパース失敗時はnull
 */
public LocalDate toDueFromDate() {
    return parseDate(dueFrom);
}

/**
 * dueTo文字列をLocalDate型に変換
 * 
 * @return LocalDate、またはパース失敗時はnull
 */
public LocalDate toDueToDate() {
    return parseDate(dueTo);
}

private String currentUserName() {
    var context = SecurityContextHolder.getContext();
    var authentication = context.getAuthentication();
    if (authentication == null) {
        throw new SecurityException("Unauthenticated");
    }
    Object principal = authentication.getPrincipal();
    if (principal == null) {
        throw new SecurityException("Unauthenticated");
    }
    if (principal instanceof UserDetails userDetails) {
        return userDetails.getUsername();
    }
    return String.valueOf(principal);
}

public PageResult<TodoItem> search(
        String keyword,
        Boolean completed,
        java.time.LocalDate dueDateFrom,
        java.time.LocalDate dueDateTo,
        int pageNumber,
        int pageSize) {

    String ownerName = currentUserName();
    var condition = new TodoSearchCondition(
            ownerName, keyword, completed, dueDateFrom, dueDateTo, pageNumber, pageSize);
    List<TodoItem> items = todoRepository.search(condition).stream()
            .map(TodoItem::fromEntity)
            .toList();
    long total = todoRepository.count(condition);

    log.info(
            "TODO検索: owner={}, keyword={}, completed={}, dueDateFrom={}, dueDateTo={}, page={}/{}, 結果={}件/全{}件",
            ownerName, keyword, completed, dueDateFrom, dueDateTo, pageNumber, pageSize, items.size(), total);

    return new PageResult<>(items, total, pageNumber, pageSize);
}
